String output = new String(p.getInputStream().readAllBytes());
p.waitFor(10, TimeUnit.SECONDS);
output.lines().limit(5).forEach(System.out::println);

// Colored pointers to technika, w ktorej ZGC wykorzystuje kilka NIEUZYWANYCH bitow w
// 64-bitowym wskazniku (referencji) do zakodowania metadanych o stanie obiektu WPROST
// w samym wskazniku - np. czy obiekt zostal juz przeniesiony/zremapowany w biezacym cyklu
// GC. Load barrier to maly fragment kodu wstawiany przez JIT przy KAZDYM odczycie
// referencji z pamieci - sprawdza 'kolor' wskaznika, a jesli obiekt zostal juz przeniesiony
// w trakcie wspolbieznej kompakcji, bariera SAMA naprawia referencje w locie (self-healing),
// zanim watek aplikacji zauwazy jakakolwiek zmiane.

// Brooks pointer to DODATKOWE SLOWO pamieci umieszczone tuz PRZED danymi kazdego obiektu
// na stercie - dziala jako wskaznik do 'aktualnej' kopii samego siebie (normalnie wskazuje
// sam na siebie). Gdy Shenandoah przenosi obiekt wspolbieznie, aktualizuje TEN wskaznik,
// zeby wskazywal na nowa lokalizacje - kazdy odczyt obiektu 'przechodzi przez' ten
// wskaznik, wiec trafia do aktualnych danych, nawet jesli watek aplikacji trzyma 'stara'
// referencje. Roznica wzgledem ZGC: Shenandoah trzyma informacje o przeniesieniu JAKO
// OSOBNE POLE przy obiekcie (dodatkowa pamiec na obiekt), a ZGC koduje ja WEWNATRZ SAMEGO
// wskaznika (bity adresu) - dwie rozne 'lokalizacje' tej samej idei.

Path javaExe = Path.of(System.getProperty("java.home"), "bin", "java");
ProcessBuilder pb = new ProcessBuilder(javaExe.toString(), "-XX:+UseZGC", "-version");
pb.redirectErrorStream(true);
Process p = pb.start();
String output = new String(p.getInputStream().readAllBytes());
boolean finished = p.waitFor(10, TimeUnit.SECONDS);
if (!finished) p.destroyForcibly();
System.out.println("Kod wyjscia: " + (finished ? p.exitValue() : -1));
System.out.println("Pierwsza linia: " + output.lines().findFirst().orElse("(brak)"));

// (kod identyczny jak w Zadaniu 6, ze zmiana flagi na -XX:+UseShenandoahGC)
// Jesli kolektor jest niedostepny na tej maszynie (jak potwierdzono w teorii lekcji dla
// OpenJDK 25.0.2), typowy blad to "Unrecognized VM option 'UseShenandoahGC'" lub podobny
// komunikat informujacy, ze ta flaga nie istnieje w tym konkretnym buildzie JDK.

// 1. Bariery (load barrier w ZGC, odczyt przez Brooks pointer w Shenandoah) wykonuja sie
//    przy KAZDYM dostepie do referencji - dodatkowy narzut na kazda operacje.
// 2. Wiecej watkow GC dziala WSPOLBIEZNIE z aplikacja - zabiera cykle CPU, ktore inaczej
//    trafilyby do watkow roboczych aplikacji (nizsza przepustowosc/throughput).
// 3. Dodatkowa pamiec: colored pointers wymagaja odpowiednio zarezerwowanej przestrzeni
//    adresowej, Brooks pointer to dodatkowe slowo NA KAZDY obiekt na stercie.

// Scenariusz: system tradingowy o wysokiej czestotliwosci (HFT), gdzie kazda transakcja
// musi zostac przetworzona z gwarantowanym opoznieniem p99 ponizej 1 milisekundy, bo
// nawet niewielkie opoznienie moze oznaczac utrate korzystnej ceny na rynku. G1, mimo
// konfigurowalnego celu -XX:MaxGCPauseMillis, WCIAZ moze okazjonalnie przekroczyc ten cel
// (np. podczas dlugiej fazy Mixed Collection lub evacuation failure) - te 'wyjatki od
// reguly' sa nie do zaakceptowania w systemie z twardym SLA. ZGC, ktorego pauzy sa
// submilisekundowe NIEZALEZNIE od okolicznosci (bo niemal cala praca dzieje sie
// wspolbieznie), jest jedynym realistycznym wyborem dla takiego zastosowania, mimo
// akceptowanego kosztu w postaci nizszego surowego throughput.

static boolean isUnsupportedOptionError(String jvmOutput) {
    String lower = jvmOutput.toLowerCase();
    return lower.contains("unrecognized vm option") || lower.contains("is unsupported");
}

System.out.println(isUnsupportedOptionError("Error: Unrecognized VM option 'UseShenandoahGC'"));
System.out.println(isUnsupportedOptionError("OpenJDK 64-Bit Server VM (build 25.0.2)"));

String g1Output = runAndCapture("-Xlog:gc"); // bez dodatkowej flagi kolektora = G1
String zgcOutput = runAndCapture("-XX:+UseZGC", "-Xlog:gc");
System.out.println("G1: " + g1Output.lines().count() + " linii");
System.out.println("ZGC: " + zgcOutput.lines().count() + " linii (jesli dostepny)");
// Format nazw faz rozni sie znaczaco - G1 uzywa 'Pause Young'/'Mixed', ZGC uzywa wlasnych
// nazw faz jak 'Garbage Collection' z rozbiciem na fazy Mark Start/Relocate Start itp.

for (String flag : new String[]{null, "-XX:+UseZGC"}) {
    long start = System.nanoTime();
    List<String> cmd = new ArrayList<>(List.of(javaExe.toString()));
    if (flag != null) cmd.add(flag);
    cmd.addAll(List.of("-Xlog:gc", "-cp", classesDir.toString(), "AllocatorDemo"));
    ProcessBuilder pb = new ProcessBuilder(cmd);
    pb.redirectErrorStream(true);
    Process p = pb.start();
    p.getInputStream().readAllBytes();
    p.waitFor(10, TimeUnit.SECONDS);
    long ms = (System.nanoTime() - start) / 1_000_000;
    System.out.println((flag == null ? "G1" : flag) + ": " + ms + "ms");
}
