// Wymaganie aplikacji                              | Zalecany kolektor
// -------------------------------------------------|-------------------
// Typowa aplikacja webowa/biznesowa (bez ekstremow) | G1 (domyslny, dobry kompromis)
// Nocny job ETL/batch processing, brak uzytkownikow | Parallel (max throughput)
// System transakcyjny z SLA opoznien < 1ms           | ZGC (submilisekundowe pauzy)
// Srodowisko Red Hat/OpenShift z podobnymi wymogami | Shenandoah (jesli dostepny w buildzie)

class GcCollectorProbe {
    boolean isAvailable(String collectorFlag) throws IOException, InterruptedException {
        Path javaExe = Path.of(System.getProperty("java.home"), "bin", "java");
        ProcessBuilder pb = new ProcessBuilder(javaExe.toString(), collectorFlag, "-version");
        pb.redirectErrorStream(true);
        Process p = pb.start();
        String output = new String(p.getInputStream().readAllBytes());
        boolean finished = p.waitFor(10, TimeUnit.SECONDS);
        if (!finished) { p.destroyForcibly(); return false; }
        if (p.exitValue() == 0) return true;
        String lower = output.toLowerCase();
        return !(lower.contains("unrecognized vm option") || lower.contains("is unsupported"));
    }
}

