static String runWithFallback(GcCollectorProbe probe, String... preferredFlags) throws Exception {
    for (String flag : preferredFlags) {
        if (probe.isAvailable(flag)) {
            System.out.println("Uzyto: " + flag);
            return flag;
        }
    }
    System.out.println("Zaden z preferowanych kolektorow niedostepny - fallback na domyslny G1");
    return null;
}

