// Raport (przykladowy, na podstawie OpenJDK 25.0.2 uzywanego w tym kursie): Serial,
// Parallel, G1 i ZGC sa DOSTEPNE w tym buildzie JDK - wszystkie 4 uruchamiaja sie
// poprawnie z odpowiednia flaga. Shenandoah NATOMIAST jest NIEDOSTEPNY - JVM zglasza
// blad 'Unrecognized VM option' dla -XX:+UseShenandoahGC, co oznacza, ze ten konkretny
// build OpenJDK nie zostal skompilowany z obsluga Shenandoah (to typowe dla wielu
// standardowych dystrybucji - Shenandoah bywa czesciej wbudowany w buildy Red
// Hat/OpenJDK dedykowane RHEL). Dla REALNEGO projektu oznacza to, ze przed zalozeniem
// uzycia konkretnego kolektora na produkcji, NALEZY zweryfikowac jego dostepnosc na
// docelowej platformie/dystrybucji JDK, zamiast polegac wylacznie na dokumentacji ogolnej.

record BenchmarkResult(String name, boolean available, long timeMs, long gcLines) { }

Map<String, String> collectors = new LinkedHashMap<>();
collectors.put("Serial", "-XX:+UseSerialGC");
collectors.put("Parallel", "-XX:+UseParallelGC");
collectors.put("G1", "-XX:+UseG1GC");
collectors.put("ZGC", "-XX:+UseZGC");
collectors.put("Shenandoah", "-XX:+UseShenandoahGC");

List<BenchmarkResult> results = new ArrayList<>();
for (var entry : collectors.entrySet()) {
    long start = System.nanoTime();
    ProcessBuilder pb = new ProcessBuilder(javaExe.toString(), entry.getValue(), "-Xlog:gc", "-cp", classesDir.toString(), "AllocatorDemo");
    pb.redirectErrorStream(true);
    Process p = pb.start();
    String output = new String(p.getInputStream().readAllBytes());
    boolean finished = p.waitFor(10, TimeUnit.SECONDS);
    if (!finished) p.destroyForcibly();
    long ms = (System.nanoTime() - start) / 1_000_000;
    boolean available = finished && p.exitValue() == 0;
    long gcLines = output.lines().filter(l -> l.contains("GC") || l.contains("Pause")).count();
    results.add(new BenchmarkResult(entry.getKey(), available, ms, gcLines));
}

System.out.printf("%-12s | %-10s | %-8s | %s%n", "Kolektor", "Dostepny", "Czas(ms)", "Linie GC");
for (BenchmarkResult r : results) {
    System.out.printf("%-12s | %-10s | %-8d | %d%n", r.name(), r.available(), r.timeMs(), r.gcLines());
}
